import React, { useEffect, useState } from "react";
import StudentList from "./StudentList";
import {
  message,
  Button,
  DatePicker,
  Divider,
  Modal,
  Space,
  Table,
  Tag,
  Typography,
  Tabs,
} from "antd";
import TermFeeList from "./TermFeeList";
import moment from "moment";
import baseAPI from "../../api/baseAPI";
import EditAcademicYearModal from "./EditAcademicYearModal";
import TermFeeItem from "./TermFeeItem";

const { Text } = Typography;

export default function Main() {
  const [year, setYear] = useState(moment().format("YYYY"));
  const [academicYear, setAcademicYear] = useState(null);
  const [openAcademicYearModal, setOpenAcademicYearModal] = useState(false);
  const [messageApi, contextHolder] = message.useMessage();

  useEffect(() => {
    fetchAcademicYear();
  }, [year]);

  const onChange = (key) => {
    console.log(key);
  };

  const onChangeYear = (_, dateString) => {
    if (dateString) {
      setYear(dateString);
    }
  };

  const fetchAcademicYear = async () => {
    const result = await baseAPI.get(`/academic/year/${year}`);
    const [data] = result.data;
    setAcademicYear(data);
  };

  const updateAcademicYear = async (data) => {
    await baseAPI
      .post(`/academic/year`, data)
      .then((res) => {
        Modal.success({
          title: `อัพเดตปีการศึกษาสำเร็จ`,
          // content: "",
          centered: true,
        });
        // console.log(academicYear.year, data);
        if (academicYear.year === Number(data.year)) {
          setAcademicYear({ ...academicYear, status: data.status });
        }
      })
      .catch((err) => {
        Modal.success({
          title: `เกิดข้อผิดพลาด`,
          content: "Error: " + err.message,
          centered: true,
        });
      });
  };

  const handleEditAcademicYear = () => {
    setOpenAcademicYearModal(true);
  };

  const handleSubmitAcademicYear = (data) => {
    // console.log("Submit Year", data);
    updateAcademicYear(data);
    setOpenAcademicYearModal(false);
  };

  const items = [
    {
      key: "1",
      label: "รายการชำระ",
      children: <StudentList year={year} />,
    },
    {
      key: "2",
      label: "ค่าเทอม",
      children: <TermFeeList year={year} />,
    },
    {
      key: "3",
      label: "รายการค่าใช้จ่าย (ใบเสร็จ)",
      children: <TermFeeItem year={year} />,
    },
  ];

  return (
    <div>
      {contextHolder}
      <h2>รายการชำระค่าเทอม</h2>
      <Divider />
      <div style={{ justifyContent: "space-between", display: "flex" }}>
        <Space>
          <Text strong>เลือกปีการศึกษา</Text>
          <DatePicker picker="year" onChange={onChangeYear} />
          <Text strong>{moment(year).add(543, "years").format("YYYY")}</Text>
        </Space>
        <Button onClick={handleEditAcademicYear}>เพิ่ม/แก้ไข ปีการศึกษา</Button>
      </div>

      <Divider />

      <div
        style={{
          flexDirection: "column",
          alignItems: "center",
          display: "flex",
        }}
      >
        {academicYear ? (
          <>
            <h3>ปีการศึกษา {Number(year) + 543}</h3>
            <Text
              type={academicYear?.status === "เปิดรับ" ? "success" : "danger"}
            >
              {" "}
              (สถานะ {academicYear?.status}ชำระ)
            </Text>
          </>
        ) : (
          <h3>ไม่มีข้อมูลปีการศึกษา</h3>
        )}
      </div>
      {academicYear && (
        <Tabs defaultActiveKey="1" items={items} onChange={onChange} />
      )}

      <EditAcademicYearModal
        open={openAcademicYearModal}
        onClose={setOpenAcademicYearModal}
        onSubmit={handleSubmitAcademicYear}
      />
    </div>
  );
}
