export const removeZeroValueObj = (item) =>
  Object.keys(item)
    .filter((key) => item[key] !== 0 && item[key] !== null)
    .reduce((newObj, key) => {
      newObj[key] = item[key];
      return newObj;
    }, {});

export const trimAllValueObj = (item) => {
  // trim all values object
  Object.keys(item).map(
    (e) => (item[e] = typeof item[e] == "string" ? item[e].trim() : item[e])
  );
  return item;
};

export const currencyFormat = (amount) => {
  return new Intl.NumberFormat("th-TH", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);
};

export const currencyFormatTH = (amount) => {
  return new Intl.NumberFormat("th-TH", {
    style: "currency",
    currency: "THB",
  }).format(amount);

  // return Number(amount)
  // .toFixed(2)
  // .replace(/\d(?=(\d{3})+\.)/g, "$&,");
};

export const extractNumbers = (input) => {
  // ใช้ Regular Expression เพื่อค้นหาเฉพาะตัวเลขใน string
  return input.match(/\d+/g)?.join("") || "";
};

export const getBase64ImageFromURL = (url) => {
  return new Promise((resolve, reject) => {
    var img = new Image();
    img.setAttribute("crossOrigin", "anonymous");

    img.onload = () => {
      var canvas = document.createElement("canvas");
      canvas.width = img.width;
      canvas.height = img.height;

      var ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0);

      var dataURL = canvas.toDataURL("image/png");

      resolve(dataURL);
    };

    img.onerror = (error) => {
      reject(error);
    };

    img.src = url;
  });
};

export function formatThreeDigits(number) {
  return number.toString().padStart(3, "0");
}
