import React, { useEffect, useState } from "react";
import baseAPI from "../../api/baseAPI";
import {
  message,
  Button,
  DatePicker,
  Divider,
  Modal,
  Space,
  Table,
  Tag,
  Tooltip,
  Typography,
  Select,
} from "antd";
import { DollarOutlined, ClockCircleOutlined } from "@ant-design/icons";
import { currencyFormatTH } from "../../utils/Utils";
import moment from "moment";
import EditTermPaymentModal from "./EditTermPaymentModal";
import TermFeeHistoryModal from "./TermFeeHistoryModal";

import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import { generateReceiptPDF } from "./pdf/Receipt";
import ReceiptTypeModal from "./ReceiptTypeModal";
import { generateTemporaryReceiptPDF } from "./pdf/ReceiptTemporary";
import PaymentListExcel from "./excel/PaymentListExcel";

//ต้องระบุตามชื่อของ ไฟล์ font
pdfMake.fonts = {
  THSarabunNew: {
    normal: "THSarabunNew.ttf",
    bold: "THSarabunNew Bold.ttf",
    italics: "THSarabunNew Italic.ttf",
    bolditalics: "THSarabunNew BoldItalic.ttf",
  },
  AngsanaNew: {
    normal: "AngsanaNew.ttf",
    bold: "AngsanaNew Bold.ttf",
    italics: "AngsanaNew Italic.ttf",
    bolditalics: "AngsanaNew Bold Italic.ttf",
  },
  Roboto: {
    normal: "Roboto-Regular.ttf",
    bold: "Roboto-Medium.ttf",
    italics: "Roboto-Italic.ttf",
    bolditalics: "Roboto-MediumItalic.ttf",
  },
};
pdfMake.vfs = pdfFonts.pdfMake.vfs;

const { Text } = Typography;
export default function StudentList({ year }) {
  const [studentList, setStudentList] = useState([]);
  const [studentListHolders, setStudentListHolders] = useState([]);
  const [gradeList, setGradeList] = useState([]);
  const [termFeeList, setTermFeeList] = useState([]);
  const [dataSelected, setDataSelected] = useState(null);
  const [openEditTermModal, setOpenEditTermModal] = useState(false);
  const [messageApi, contextHolder] = message.useMessage();
  const [openPaymentListModal, setOpenPaymentListModal] = useState(false);
  const [openReceiptTypeModal, setOpenReceiptTypeModal] = useState(false);
  const [dataPDF, setDataPDF] = useState({});

  useEffect(() => {
    getStudentList();
  }, [year]);

  const getStudentList = async () => {
    const result = await baseAPI.get(`/terms`, {
      params: { year },
    });
    const data = result.data;
    // console.log("Payment List", data);
    setStudentList(data);
    setStudentListHolders(data);

    const sortedValues = data?.toSorted((a, b) =>
      a.grade_level?.localeCompare(b.grade_level, "th", { numeric: true })
    );
    const uniqueGrade = new Set();
    const uniqueData = sortedValues.filter((item) => {
      if (uniqueGrade.has(item.grade_level)) {
        return false;
      } else {
        uniqueGrade.add(item.grade_level);
        return true;
      }
    });
    setGradeList(uniqueData);
  };

  const fetchTermFeeHistory = async (value) => {
    const result = await baseAPI.get(`/payments/users`, {
      params: { user_id: value.id, year },
    });
    const data = result.data;

    setTermFeeList(data);
    setOpenPaymentListModal(true);
  };

  const handleCancelPayment = async (data) => {
    await baseAPI
      .delete(`/payments/${data.id}`)
      .then(() => {
        messageApi.open({
          type: "success",
          content: "ลบรายการสำเร็จ",
        });
        // const newList = studentList.filter((item) => item.id !== data.id);
        // const newListHolder = studentListHolders.filter(
        //   (item) => item.id !== data.id
        // );

        // setStudentList(newList);
        // setStudentListHolders(newListHolder);
        getStudentList();
      })
      .catch((err) => {});
    setOpenPaymentListModal(false);
  };

  const handleClickPaymentHistory = (rec) => {
    fetchTermFeeHistory(rec);
  };

  const updatePayment = async (data) => {
    await baseAPI
      .post(`/payments/`, data)
      .then((res) => {
        messageApi.open({
          type: "success",
          content: "อัพเดตข้อมูลสำเร็จ",
        });
        getStudentList();
      })
      .catch((err) => {
        Modal.error({
          title: `ผิดพลาด`,
          content: "Error: " + err.message,
          centered: true,
        });
      });
  };

  const handleClickEdit = (data) => {
    setOpenEditTermModal(true);
    // console.log("EDIT", data);
    setDataSelected(data);
  };

  const handleSubmitTerm = (data) => {
    Modal.confirm({
      title: `ยืนยันข้อมูล`,
      content: `ตรวจสอบข้อมูลถูกต้องแล้ว ต้องการบันทึกข้อมูล?`,
      centered: true,
      onOk: () => {
        // console.log("SUBMIT", { ...data, year });
        updatePayment({ ...data, year });
        setOpenEditTermModal(false);
      },
    });
  };

  const handleChangeGradeLevels = (value) => {
    const result = studentListHolders.filter(
      (item) => item.grade_level === value
    );
    setStudentList(result);
  };

  const handlePrintReceipt = async (data) => {
    const result = await baseAPI.get(`/receipt/payment/${data.id}`);
    console.log("PRINT", result.data);
    setOpenPaymentListModal(false);
    setOpenReceiptTypeModal(true);

    setDataPDF(result.data);
  };

  const handleSubmitModal = (value) => {
    // setSelectedReceiptType(value);
    // console.log("ประเภทใบเสร็จที่เลือก:", value);
    setOpenReceiptTypeModal(false);
    if (value !== 3) {
      onDownloadReceiptPDF(dataPDF, value);
    } else {
      onDownloadTemporaryReceiptPDF(dataPDF);
      // console.log("Value:", value);
    }
    // ทำอย่างอื่นกับค่าที่เลือก เช่น ส่งไปยัง API
  };

  const onDownloadReceiptPDF = async (data, type) => {
    const docDefinition = await generateReceiptPDF(data, type);
    pdfMake.createPdf(docDefinition).open();
  };

  const onDownloadTemporaryReceiptPDF = async (data) => {
    const docDefinition = await generateTemporaryReceiptPDF(data);
    pdfMake.createPdf(docDefinition).open();
  };

  const columns = [
    // {
    //   title: "ชื่อผู้ใช้งาน",
    //   dataIndex: "user_name",
    //   key: "user_name",
    // },
    {
      title: "เลขประจำตัว",
      dataIndex: "student_id",
      key: "student_id",
    },
    {
      title: "ชื่อ-สกุล",
      //   dataIndex: 'address',
      key: "fullname",
      render: (recode) => {
        return (
          <Text>
            {recode.title_name}
            {recode.fullname}
          </Text>
        );
      },
    },
    {
      title: "ระดับชั้น",
      dataIndex: "grade_level",
      key: "grade_level",
    },
    {
      title: "ประเภทนักเรียน",
      dataIndex: "user_type",
      key: "user_type",
    },
    {
      title: `ค่าเทอม`,
      // dataIndex: "user_type",
      key: "term_fees",
      render: (recode) => {
        return recode.term_fees ? (
          <>
            <Space direction="vertical">
              {/* <Text>ปีการศึกษา {recode.academic_year + 543}</Text> */}
              <Text>{currencyFormatTH(recode.term_fees)}</Text>
            </Space>
          </>
        ) : (
          <Text>ไม่พบข้อมูล</Text>
        );
      },
    },
    {
      title: "ชำระเทอม 1",
      // dataIndex: "user_type",
      key: "total_paid_sem1",
      render: (recode) => {
        return (
          <Space direction="vertical">
            {recode.year ? (
              recode?.total_paid_sem1 > 0 ? (
                recode?.term_fees ? (
                  recode?.total_paid_sem1 >= recode?.term_fees ? (
                    <Tag color="success">
                      {currencyFormatTH(recode?.total_paid_sem1)}
                    </Tag>
                  ) : (
                    <Tag color="processing">
                      {currencyFormatTH(recode?.total_paid_sem1)}
                    </Tag>
                  )
                ) : (
                  <Tag>{currencyFormatTH(recode?.total_paid_sem2)}</Tag>
                )
              ) : (
                <Text>-</Text>
              )
            ) : null}
          </Space>
        );
      },
    },
    {
      title: "ชำระเทอม 2",
      // dataIndex: "user_type",
      key: "total_paid_sem2",
      render: (recode) => {
        return (
          <Space direction="vertical">
            {recode.year ? (
              recode?.total_paid_sem2 > 0 ? (
                recode?.term_fees ? (
                  recode?.total_paid_sem2 >= recode?.term_fees ? (
                    <Tag color="success">
                      {currencyFormatTH(recode?.total_paid_sem2)}
                    </Tag>
                  ) : (
                    <Tag color="processing">
                      {currencyFormatTH(recode?.total_paid_sem2)}
                    </Tag>
                  )
                ) : (
                  <Tag>{currencyFormatTH(recode?.total_paid_sem2)}</Tag>
                )
              ) : (
                <Text>-</Text>
              )
            ) : null}
          </Space>
        );
      },
    },
    {
      title: "",
      // dataIndex: "edit",
      key: "edit",
      render: (recode) => {
        return (
          <Space>
            <Tooltip title="ชำระค่าเทอม">
              <Button
                type="primary"
                shape="circle"
                icon={<DollarOutlined />}
                onClick={() => handleClickEdit(recode)}
              />
            </Tooltip>
            <Tooltip title="ประวัติการชำระ">
              <Button
                // type="primary"
                shape="circle"
                icon={<ClockCircleOutlined />}
                onClick={() => handleClickPaymentHistory(recode)}
              />
            </Tooltip>
          </Space>
        );
      },
    },
  ];

  return (
    <>
      {contextHolder}

      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          marginBottom: 16,
        }}
      >
        <Space>
          <Text strong>เลือกระดับชั้น</Text>
          <Select
            showSearch
            style={{ width: 200 }}
            placeholder="เลือกชั้นปี"
            onChange={handleChangeGradeLevels}
            filterOption={(input, option) =>
              (option?.label ?? "").toLowerCase().includes(input.toLowerCase())
            }
            options={gradeList.map((grade) => ({
              label: grade.grade_level,
              value: grade.grade_level,
            }))}
          />
        </Space>
        <Space>
          <Tag color="success">ชำระครบแล้ว</Tag>
          <Tag color="processing">ชำระยังไม่ครบ</Tag>
          <Tag>ไม่มีข้อมูลค่าเทอม</Tag>
        </Space>
      </div>
      <PaymentListExcel data={studentList} year={year} />
      <Table columns={columns} dataSource={studentList} bordered />
      <EditTermPaymentModal
        data={dataSelected}
        onSubmit={handleSubmitTerm}
        open={openEditTermModal}
        onClose={setOpenEditTermModal}
      />
      <TermFeeHistoryModal
        open={openPaymentListModal}
        onClose={setOpenPaymentListModal}
        data={termFeeList}
        onDelete={handleCancelPayment}
        onPrint={handlePrintReceipt}
      />
      <ReceiptTypeModal
        open={openReceiptTypeModal}
        onClose={setOpenReceiptTypeModal}
        onSubmit={handleSubmitModal}
      />
    </>
  );
}
