import React, { useEffect, useState } from "react";
import {
  Button,
  Divider,
  Modal,
  Space,
  Table,
  Tooltip,
  Typography,
} from "antd";
import { EditOutlined, UnorderedListOutlined } from "@ant-design/icons";
import AddFeeItemModal from "./AddFeeItemModal";
import baseAPI from "../../api/baseAPI";
import FeeItemModal from "./FeeItemModal";
import moment from "moment";
import { currencyFormat } from "../../utils/Utils";

const { Text } = Typography;
export default function TermFeeItem({ onSubmit }) {
  const [dataSource, setDataSource] = useState([]);
  const [openAddFeeItemMadal, setOpenAddFeeItemModal] = useState(false);
  const [openFeeItemModal, setOpenFeeItemModal] = useState(false);
  const [dataSelected, setDataSelected] = useState(null);
  const [termFeeList, setTermFeeList] = useState([]);
  const [termFeeListHolder, setTermFeeListHolder] = useState([]);
  const [gradeList, setGradeList] = useState([]);

  useEffect(() => {
    fetchFeeItemList();
    getTermFeeList(moment().format("YYYY"));
  }, []);

  const getTermFeeList = async (year) => {
    const result = await baseAPI.get(`/term-fees/genaral`, {
      params: { year },
    });
    const data = result.data;
    setTermFeeList(data);
    setTermFeeListHolder(data);
    // console.log("DATA", data);

    // const sortedValues = data.toSorted((a, b) => b.donate - a.donate);
    const uniqueGrade = new Set();
    const uniqueData = data.filter((item) => {
      if (uniqueGrade.has(item.grade_level)) {
        return false;
      } else {
        uniqueGrade.add(item.grade_level);
        return true;
      }
    });
    setGradeList(uniqueData);
  };

  const fetchFeeItemList = async () => {
    const result = await baseAPI.get(`/fee-items`);
    // console.log(result.data);
    setDataSource(result.data);
  };
  const handleClickAddItem = () => {
    setOpenAddFeeItemModal(true);
  };

  const postFeeItem = async (data) => {
    await baseAPI
      .post(`/fee-items`, { name: data })
      .then((res) => {
        Modal.success({
          title: `อัพเดตรายการค่าใช้จ่ายสำเร็จ`,
          // content: "",
          centered: true,
        });
        setOpenAddFeeItemModal(false);
        setDataSource((pre) => [...pre, { name: data }]);
      })
      .catch((err) => {
        Modal.success({
          title: `เกิดข้อผิดพลาด`,
          content: "Error: " + err.message,
          centered: true,
        });
      });
  };

  const handleSubmitFeeItem = (data) => {
    postFeeItem(data);
  };

  const handleClicItemList = (data) => {
    console.log("Edit", data);
    setDataSelected(data);
    setOpenFeeItemModal(true);
  };

  const columns = [
    {
      title: "ระดับชั้น",
      dataIndex: "grade_level",
      key: "grade_level",
    },
    {
      title: "ประเภทนักเรียน",
      dataIndex: "user_type",
      key: "user_type",
    },
    {
      title: "ค่าเทอม",
      // dataIndex: "term_fees",
      key: "term_fees",
      render: (recode) => {
        return (
          <>
            <Text> {currencyFormat(recode.term_fees)}</Text>
          </>
        );
      },
    },

    {
      title: "",
      // dataIndex: "edit",
      key: "edit",
      render: (recode) => {
        return (
          <Space>
            {/* <Tooltip title="แก้ไขค่าเทอม">
              <Button
                type="primary"
                shape="circle"
                icon={<EditOutlined />}
                onClick={() => handleClickEdit(recode)}
              />
            </Tooltip> */}
            <Tooltip title="ค่าใช้จ่าย (ใบเสร็จ)">
              <Button
                type="link"
                shape="circle"
                icon={<UnorderedListOutlined />}
                onClick={() => handleClicItemList(recode)}
              >
                ดูค่าใช้จ่าย
              </Button>
            </Tooltip>
          </Space>
        );
      },
    },
  ];

  const columnItems = [
    // {
    //   title: "ระดับชั้น",
    //   dataIndex: "grade_level",
    //   key: "grade_level",
    // },
    {
      title: "ชื่อรายการ",
      dataIndex: "name",
      key: "name",
    },
  ];

  return (
    <div>
      <Table columns={columns} dataSource={termFeeList} bordered />
      <Divider />
      <h3>รายการค่าใช้จ่าย</h3>
      {/* <Divider /> */}
      <div style={{ display: "flex", justifyContent: "flex-end" }}>
        <Button type="primary" onClick={handleClickAddItem}>
          เพิ่มรายการ
        </Button>
      </div>
      <Table
        pagination={false}
        dataSource={dataSource}
        columns={columnItems}
        size="small"
      />
      <AddFeeItemModal
        open={openAddFeeItemMadal}
        onClose={setOpenAddFeeItemModal}
        onSubmit={handleSubmitFeeItem}
      />

      <FeeItemModal
        termFee={dataSelected}
        // onSubmit={handleSubmitYear}
        open={openFeeItemModal}
        onClose={setOpenFeeItemModal}
      />
    </div>
  );
}
