import React, { useEffect, useState } from "react";
import {
  Modal,
  Button,
  Typography,
  Divider,
  Radio,
  Space,
  InputNumber,
  DatePicker,
  TimePicker,
  Image,
  Input,
  Form,
} from "antd";
// import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import moment from "moment";

const { Text } = Typography;

export default function EditTermFeeModal({ open, data, onSubmit, onClose }) {
  // const user = useSelector((state) => state.token);
  const [form] = Form.useForm();

  useEffect(() => {
    // console.log("Edit", data);
    // form.setFieldsValue({ term_fees: data.term_fees });
  }, [data]);

  const handleClose = () => {
    form.resetFields();
    onClose(false);
  };

  const handleSubmit = (values) => {
    const result = {
      ...data,
      ...values,
    };

    onSubmit(result);
    form.resetFields();
  };

  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  return (
    <Modal
      title="แก้ไขค่าเทอม"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        <Button key="submit" type="primary" onClick={form.submit}>
          บันทึก
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <div style={{ flexDirection: "column", display: "flex" }}>
          {/* <div style={{ justifyContent: "space-between", display: "flex" }}>
            <Text type="secondary">ปีการศึกษา</Text>
            <Text strong>{data?.year + 543}</Text>
          </div> */}
          <div style={{ justifyContent: "space-between", display: "flex" }}>
            <Text type="secondary">ระดับชั้น</Text>
            <Text strong>{data?.grade_level}</Text>
          </div>
          <div style={{ justifyContent: "space-between", display: "flex" }}>
            <Text type="secondary">ประเภทนักเรียน</Text>
            <Text strong>{data?.user_type}</Text>
          </div>
        </div>
        <Divider />
        <Form
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="term_fees"
            label="ค่าเทอม"
            // initialValue={data.term_fees}
            // rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <InputNumber
              size="large"
              name="term_fee"
              style={{ width: "100%" }}
              formatter={(value) =>
                `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
              }
            />
          </Form.Item>
        </Form>

        <Divider />
      </div>
    </Modal>
  );
}
