import React, { useEffect, useState } from "react";
import {
  Modal,
  Button,
  Typography,
  Divider,
  Radio,
  Space,
  InputNumber,
  DatePicker,
  TimePicker,
  Image,
  Input,
  Form,
} from "antd";
// import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import moment from "moment";

const { Text } = Typography;

export default function EditAcademicYearModal({
  open,
  data,
  onSubmit,
  onClose,
}) {
  const user = useSelector((state) => state.token);
  const [form] = Form.useForm();
  const [year, setYear] = useState("");

  useEffect(() => {
    // console.log("USER", user);
  }, [open]);

  const handleClose = () => {
    onClose(false);
    form.resetFields();
  };

  const handleSubmit = (values) => {
    const result = {
      ...values,
      year,
    };

    // console.log(result);

    onSubmit(result);
    form.resetFields();
  };

  const onChangeDate = (date, dateString) => {
    setYear(dateString);
  };

  //   const onChangeTime = (time, timeString) => {
  //     setTime(timeString);
  //   };
  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  return (
    <Modal
      title="เพิ่ม/แก้ไข ปีการศึกษา"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        <Button key="submit" type="primary" onClick={form.submit}>
          บันทึก
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <Form
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="year"
            label="ปีการศึกษา"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <DatePicker onChange={onChangeDate} picker="year" />
          </Form.Item>
          <Form.Item
            name="status"
            label="สถานะ"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
            // initialValue={eventSelect}
          >
            <Radio.Group>
              <Space>
                <Radio value={"เปิดรับ"}>เปิดรับชำระ</Radio>
                <Radio value={"ปิดรับ"}>ปิดรับชำระ</Radio>
              </Space>
            </Radio.Group>
          </Form.Item>
        </Form>

        <Divider />
      </div>
    </Modal>
  );
}
