export default function AddStudentModal({ open, onSubmit, onClose }) {
  // const user = useSelector((state) => state.token);
  const [form] = Form.useForm();

  useEffect(() => {
    // console.log("Edit", data);
    // form.setFieldsValue({ term_fees: data.term_fees });
  }, []);

  const handleClose = () => {
    form.resetFields();
    onClose(false);
  };

  const handleSubmit = (values) => {
    const user_name = values.student_id?.replace(/[^a-zA-Z0-9]/g, "");
    const idcard = values.idcard?.replace(/[^a-zA-Z0-9]/g, "");
    onSubmit({ ...values, user_name, idcard });
    // form.resetFields();
  };

  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  return (
    <Modal
      title="เพิ่มรายชื่อนักเรียน"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        <Button key="submit" type="primary" onClick={form.submit}>
          บันทึก
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <Form
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="student_id"
            label="เลขประจำตัว"
            initialValue="BDW-"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item
            name="idcard"
            label="เลขบัตรประชาชน"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item
            name="title_name"
            label="คำนำหน้าชื่อ"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              placeholder="เลือกคำนำหน้า"
              allowClear
              options={titleNameItems}
            />
          </Form.Item>
          <Form.Item
            name="fullname"
            label="ชื่อ-สกุล"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item
            name="grade_level"
            label="ระดับชั้นปี"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              placeholder="เลือกระดับชั้น"
              allowClear
              options={gradeLevelItems}
            />
          </Form.Item>
          <Form.Item
            name="user_type"
            label="ประเภทนักเรียน"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              placeholder=" เลือกประเภทนักเรียน"
              allowClear
              options={userTypeItems}
            />
          </Form.Item>
          <Form.Item name="mark" label="หมายเหตุ">
            <Input style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item
            name="payment_type"
            label="การชำระค่าเทอม"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              placeholder="เลือกประเภทการชำระค่าเทอม"
              allowClear
              options={payTypeItems}
            />
          </Form.Item>
          <Form.Item
            name="status"
            label="สถานะ"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select placeholder="เลือกสถานะ" allowClear options={statusItems} />
          </Form.Item>
        </Form>

        <Divider />
      </div>
    </Modal>
  );
}
