import React, { useState } from "react";
import { Modal, Radio, Button, Space } from "antd";

const ReceiptTypeModal = ({ open, onClose, onSubmit }) => {
  const [selectedValue, setSelectedValue] = useState(1); // ค่าเริ่มต้นเป็น 1 (ใบเสร็จแบบเต็ม)

  const handleRadioChange = (e) => {
    setSelectedValue(e.target.value);
  };

  const handleOk = () => {
    onSubmit(selectedValue); // ส่งค่าที่เลือกกลับไปยัง onSubmit
    onClose(false); // ปิด Modal
    setSelectedValue(1); // รีเซ็ตค่าที่เลือกเมื่อปิด Modal (ถ้าต้องการ)
  };

  const handleCancel = () => {
    onClose(false); // ปิด Modal
    setSelectedValue(1); // รีเซ็ตค่าที่เลือกเมื่อปิด Modal (ถ้าต้องการ)
  };

  return (
    <Modal
      title="เลือกประเภทใบเสร็จ"
      open={open}
      onOk={handleOk}
      centered
      onCancel={handleCancel}
      footer={[
        <Button key="cancel" onClick={handleCancel}>
          ยกเลิก
        </Button>,
        <Button key="submit" type="primary" onClick={handleOk}>
          ยืนยัน
        </Button>,
      ]}
    >
      <Radio.Group onChange={handleRadioChange} value={selectedValue}>
        <Space direction="vertical">
          <Radio value={1}>ใบเสร็จแบบเต็ม</Radio>
          <Radio value={2}>ใบเสร็จแบบมีส่วนลด</Radio>
          <Radio value={3}>ใบเสร็จแบบชั่วคราว</Radio>
        </Space>
      </Radio.Group>
    </Modal>
  );
};

export default ReceiptTypeModal;
