import React from "react";
import { saveAs } from "file-saver";
import ExcelJS from "exceljs";
import { Button } from "antd";
import moment from "moment";
import { currencyFormat } from "../../../utils/Utils";

export default function TermFeesListExcel({ data, year }) {
  const exportToExcel = () => {
    const workbook = new ExcelJS.Workbook();
    const worksheet1 = workbook.addWorksheet("ค่าเทอม");

    worksheet1.columns = [
      { header: "ระดับชั้น", key: "grade_level", width: 20 },
      { header: "ประเภท", key: "user_type", width: 15 },
      {
        header: "ค่าเทอม",
        key: "term_fees",
        width: 20,
        style: { alignment: { horizontal: "right" } },
      },
    ];

    worksheet1.getRow(1).eachCell((cell) => {
      cell.fill = {
        type: "pattern",
        pattern: "solid",
        fgColor: { argb: "FFCCFFCC" },
      };
      cell.font = { bold: true };
    });

    data.forEach((item, index) => {
      const termFees = Number(item.term_fees || 0);

      const row = worksheet1.addRow({
        grade_level: item.grade_level,
        user_type: item.user_type,
        term_fees: currencyFormat(termFees),
      });

      // สลับสีทุก 4 แถว
      const groupIndex = Math.floor(index / 4); // กลุ่มละ 4 แถว
      if (groupIndex % 2 === 0) {
        row.eachCell((cell) => {
          cell.fill = {
            type: "pattern",
            pattern: "solid",
            fgColor: { argb: "FFEDEDED" }, // สีเทาอ่อน
          };
        });
      }
    });

    workbook.xlsx.writeBuffer().then((buffer) => {
      const blob = new Blob([buffer], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      });
      saveAs(blob, `รายการค่าเทอมปีการศึกษา ${~~year + 543}.xlsx`);
    });
  };

  return (
    <div
      style={{
        width: "100%",
        display: "flex",
        justifyContent: "flex-end",
        marginBottom: 24,
      }}
    >
      <Button type="primary" onClick={exportToExcel}>
        ดาวน์โหลด Excel
      </Button>
    </div>
  );
}
