import React from "react";
import { saveAs } from "file-saver";
import ExcelJS from "exceljs";
import { Button } from "antd";
import moment from "moment";
import { currencyFormat } from "../../../utils/Utils";

export default function PaymentListExcel({ data, year }) {
  const exportToExcel = () => {
    const workbook = new ExcelJS.Workbook();
    const worksheet1 = workbook.addWorksheet("รายการชำระ");

    worksheet1.columns = [
      { header: "รหัสนักเรียน", key: "student_id", width: 15 },
      { header: "คำนำหน้า", key: "title_name", width: 10 },
      { header: "ชื่อ-สกุล", key: "fullname", width: 30 },
      { header: "ระดับชั้น", key: "grade_level", width: 20 },
      { header: "ประเภท", key: "user_type", width: 15 },
      {
        header: "ค่าเทอม",
        key: "term_fees",
        width: 15,
        style: { alignment: { horizontal: "right" } },
      },
      {
        header: "ชำระเทอม 1",
        key: "total_paid_sem1",
        width: 20,
        style: { alignment: { horizontal: "right" } },
      },
      {
        header: "คงเหลือ เทอม 1",
        key: "remain_sem1",
        width: 20,
        style: { alignment: { horizontal: "right" } },
      },
      {
        header: "ชำระเทอม 2",
        key: "total_paid_sem2",
        width: 20,
        style: { alignment: { horizontal: "right" } },
      },
      {
        header: "คงเหลือ เทอม 2",
        key: "remain_sem2",
        width: 20,
        style: { alignment: { horizontal: "right" } },
      },
    ];

    worksheet1.getRow(1).eachCell((cell) => {
      cell.fill = {
        type: "pattern",
        pattern: "solid",
        fgColor: { argb: "FFCCFFCC" },
      };
      cell.font = { bold: true };
    });

    data.forEach((item, index) => {
      const termFees = Number(item.term_fees || 0);
      const paidSem1 = Number(item.total_paid_sem1 || 0);
      const paidSem2 = Number(item.total_paid_sem2 || 0);

      const remainSem1 = termFees - paidSem1;
      const remainSem2 = termFees - paidSem2;

      const row = worksheet1.addRow({
        student_id: item.student_id,
        title_name: item.title_name,
        fullname: item.fullname,
        grade_level: item.grade_level,
        user_type: item.user_type,
        term_fees: currencyFormat(termFees),
        total_paid_sem1: currencyFormat(paidSem1) || 0,
        remain_sem1: currencyFormat(remainSem1 > 0 ? remainSem1 : 0),
        total_paid_sem2: currencyFormat(paidSem2) || 0,
        remain_sem2: currencyFormat(remainSem2 > 0 ? remainSem2 : 0),
      });

      // Fill alternate row background color
      if (index % 2 === 0) {
        row.eachCell((cell) => {
          cell.fill = {
            type: "pattern",
            pattern: "solid",
            fgColor: { argb: "FFEDEDED" },
          };
        });
      }

      // Apply color to total_paid_sem1 & total_paid_sem2
      const paidSem1Cell = row.getCell("total_paid_sem1");
      const paidSem2Cell = row.getCell("total_paid_sem2");

      // กำหนดสีฟอนต์ตามสถานะของการชำระ เทอม 1
      if (paidSem1 <= 0) {
        paidSem1Cell.font = { color: { argb: "FF000000" } }; // ดำ
      } else if (paidSem1 >= termFees) {
        paidSem1Cell.font = { color: { argb: "FF2E7D32" } }; // เขียว
      } else {
        paidSem1Cell.font = { color: { argb: "FFFF6F00" } }; // ส้ม
      }

      // เทอม 2
      if (paidSem2 <= 0) {
        paidSem2Cell.font = { color: { argb: "FF000000" } }; // ดำ
      } else if (paidSem2 >= termFees) {
        paidSem2Cell.font = { color: { argb: "FF2E7D32" } }; // เขียว
      } else {
        paidSem2Cell.font = { color: { argb: "FFFF6F00" } }; // ส้ม
      }
    });

    const totalSum1 = data.reduce(
      (sum, item) => sum + Number(item.total_paid_sem1),
      0
    );

    const totalSum2 = data.reduce(
      (sum, item) => sum + Number(item.total_paid_sem2),
      0
    );

    const totalRow1 = worksheet1.addRow({
      student_id: "",
      title_name: "",
      fullname: "",
      grade_level: "",
      user_type: "ยอดชำระรวม",
      term_fees: "",
      total_paid_sem1: currencyFormat(totalSum1),
      remain_sem1: "",
      total_paid_sem2: currencyFormat(totalSum2),
      remain_sem2: "",
    });

    const lastRow1 = worksheet1.lastRow;
    lastRow1.eachCell((cell) => {
      cell.fill = {
        type: "pattern",
        pattern: "solid",
        fgColor: { argb: "FFB3E5FC" },
      };
      cell.font = { bold: true };
    });

    workbook.xlsx.writeBuffer().then((buffer) => {
      const blob = new Blob([buffer], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      });
      saveAs(blob, `รายการชำระค่าเทอมปีการศึกษา ${~~year + 543}.xlsx`);
    });
  };

  return (
    <div
      style={{
        width: "100%",
        display: "flex",
        justifyContent: "flex-end",
        marginBottom: 24,
      }}
    >
      <Button type="primary" onClick={exportToExcel}>
        ดาวน์โหลด Excel
      </Button>
    </div>
  );
}
