import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";

// ข้อมูลจำลอง (Mock Data) จากโครงสร้างเดิม
// const MOCK_DATA = {
//     year: 2025,
//     term_number: 1,
//     student_id: "S40001",
//     fullname: "สมชาย ใจดี",
//     term_fees: 15000.50,
//     due_date_th: "30/12/2568" // วันที่ครบกำหนดชำระ
// };

/**
 * ฟังก์ชันจำลองเพื่อคำนวณ Ref. 1 และ Ref. 2
 * @param {object} data - ข้อมูลการชำระเงิน
 * @returns {{ref1: string, ref2: string}}
 */
const getPaymentReferences = (data) => {
  // ปี พ.ศ.
  const thaiYear = data.year + 543;
  // ดึงเฉพาะตัวเลขจาก Student ID
  const studentNumber = data.student_id.replace(/\D/g, "");

  // Ref. 1: (ปี พ.ศ. - 2500) + เลขเทอม + "0"
  // เช่น (2568 - 2500) = 68 -> Ref. 1 = "6810"
  const ref1 = thaiYear - 2500 + "" + data.term_number + "0";

  // Ref. 2: รหัสนักเรียนเฉพาะตัวเลข
  const ref2 = studentNumber;

  return { ref1, ref2 };
};

/**
 * ฟังก์ชันจัดรูปแบบสกุลเงินไทย
 * @param {number} amount - จำนวนเงิน
 * @returns {string} - จำนวนเงินในรูปแบบ "15,000.50"
 */
const currencyFormatTH = (amount) => {
  return new Intl.NumberFormat("th-TH", {
    style: "currency",
    currency: "THB",
    minimumFractionDigits: 2,
  })
    .format(amount)
    .replace("฿", "")
    .trim();
};

const QRPayment = () => {
  const location = useLocation();
  const data = location.state?.data;
  const qrcode = location.state?.qrcode;
  const [currentDateText, setCurrentDateText] = useState("");

  // คำนวณ Ref. และยอดเงินเมื่อ Component โหลด
  const { ref1, ref2 } = getPaymentReferences(data);
  const amountText = currencyFormatTH(data.term_fees);

  useEffect(() => {
    // คำนวณวันที่ปัจจุบันในรูปแบบไทย
    const today = new Date();
    const dueText = today.toLocaleDateString("th-TH", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
    setCurrentDateText(`วันที่ ${dueText}`);
  }, []);

  // ข้อมูลหน่วยงานที่แสดงในตาราง
  const paymentDetails = [
    { label: "ชื่อหน่วยงาน", value: "โรงเรียนบัวแดงวัฒนา" },
    { label: "Company Code", value: "83250" },
    { label: "Tax ID", value: "0994002773762" },
    { label: "ชื่อ-สกุล (ผู้ชำระเงิน)", value: data.fullname },
    { label: "รหัสนักเรียน", value: data.student_id },
    { label: "Ref. 1 (อ้างอิง 1)", value: ref1, mono: true, primary: true },
    { label: "Ref. 2 (อ้างอิง 2)", value: ref2, mono: true, primary: true },
  ];

  const styles = {
    // จำลองสีหลักของ Antd (Primary Blue)
    antdPrimary: "#1677ff",
    antdPrimaryBg: "#e6f4ff", // Light blue background
    antdCardShadow:
      "0 1px 2px 0 rgba(0, 0, 0, 0.03), 0 1px 6px -1px rgba(0, 0, 0, 0.02), 0 2px 4px 0 rgba(0, 0, 0, 0.02)",
    antdCardHeader: {
      borderBottom: "1px solid #f0f0f0",
      padding: "16px 24px",
      marginBottom: "0",
      fontWeight: "500",
      fontSize: "16px",
      color: "rgba(0, 0, 0, 0.88)",
    },
    antdCardBody: {
      padding: "24px",
    },
    antdAlertWarning: {
      backgroundColor: "#fffbe6",
      border: "1px solid #ffe58f",
      color: "rgba(0, 0, 0, 0.88)",
      padding: "8px 15px",
      borderRadius: "6px",
      marginTop: "16px",
    },
    infoLabel: {
      color: "rgba(0, 0, 0, 0.45)",
      fontSize: "12px",
      marginBottom: "4px",
      display: "block",
    },
    infoValue: {
      color: "rgba(0, 0, 0, 0.88)",
      fontSize: "14px",
      fontWeight: "600",
    },
  };

  const AntdCard = ({ title, extra, children, bodyStyle = {} }) => (
    <div
      style={{
        backgroundColor: "#fff",
        borderRadius: "8px",
        boxShadow: styles.antdCardShadow,
        marginBottom: "24px",
      }}
    >
      <div
        style={{
          ...styles.antdCardHeader,
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <span style={{ fontWeight: "600" }}>{title}</span>
        {extra}
      </div>
      <div style={{ ...styles.antdCardBody, ...bodyStyle }}>{children}</div>
    </div>
  );

  const AntdRow = ({ children, style = {} }) => (
    <div
      style={{ display: "flex", flexWrap: "wrap", margin: "-8px", ...style }}
    >
      {children}
    </div>
  );

  const AntdCol = ({ span, children }) => {
    // Antd uses 24 columns grid. Here we simulate 2 columns (12/24)
    const width = span === 12 ? "50%" : "100%";
    return <div style={{ width: width, padding: "8px" }}>{children}</div>;
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: "#f0f2f5",
        padding: "24px",
        display: "flex",
        justifyContent: "center",
        alignItems: "flex-start",
      }}
    >
      {/* Payment Card Container (Simulating Antd Card) */}
      <div style={{ width: "100%", maxWidth: "560px" }}>
        <AntdCard
          title="ใบแจ้งชำระเงิน (Bill Payment)"
          extra={
            <span style={{ fontSize: "12px", color: "rgba(0, 0, 0, 0.45)" }}>
              {currentDateText}
            </span>
          }
        >
          {/* Amount Display (Simulating an Alert/Result block) */}
          <div
            style={{
              backgroundColor: styles.antdPrimaryBg,
              border: `1px solid ${styles.antdPrimary}`,
              //   padding: "16px",
              borderRadius: "4px",
              marginBottom: "16px",
              textAlign: "center",
            }}
          >
            <p
              style={{
                fontSize: "16px",
                color: styles.antdPrimary,
                marginBottom: "4px",
              }}
            >
              ยอดชำระรวม (THB)
            </p>
            <p
              style={{
                fontSize: "32px",
                fontWeight: "900",
                color: styles.antdPrimary,
                letterSpacing: "1px",
              }}
            >
              {amountText}
            </p>
          </div>

          {/* QR Code Area (The main focus - Simulating a large dashed area) */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              padding: "32px",
              backgroundColor: "#fafafa",
              borderRadius: "8px",
              border: "2px dashed #d9d9d9",
              marginBottom: "24px",
            }}
          >
            <h3
              style={{
                fontSize: "16px",
                fontWeight: "bold",
                color: "rgba(0, 0, 0, 0.88)",
                marginBottom: "16px",
              }}
            >
              สแกนเพื่อชำระเงิน (QR Code Payment)
            </h3>

            {/* Mock QR Code Image Placeholder */}
            <div
              style={{
                width: "200px",
                height: "200px",
                backgroundColor: "#fff",
                // padding: "10px",
                borderRadius: "4px",
                boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
              }}
            >
              <img
                src={qrcode}
                alt="Payment QR Code"
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                  borderRadius: "2px",
                }}
              />
            </div>

            <p
              style={{
                marginTop: "16px",
                fontSize: "13px",
                color: "rgba(0, 0, 0, 0.65)",
              }}
            >
              Capture หน้าจอเพื่อนำ QR ไปชำระใน Mobile Banking App
            </p>
            <p
              style={{
                marginTop: "16px",
                fontSize: "14px",
                color: "red",
              }}
            >
              **เมื่อชำระแล้วกรุณาแจ้งชำระ โดยส่งสลิปให้ไลน์โรงเรียน ขอบคุณค่ะ**
            </p>
          </div>

          {/* Due Date Alert (Simulating Antd Alert component) */}
          {/* <div style={styles.antdAlertWarning}>
                        <p style={{ fontSize: '14px', fontWeight: '600', color: '#fa8c16' }}>
                            โปรดชำระเงินภายในวันที่ {MOCK_DATA.due_date_th}
                        </p>
                        <p style={{ fontSize: '12px', color: 'rgba(0, 0, 0, 0.65)' }}>
                            * หากพ้นกำหนดจะต้องเสียค่าปรับ 200 บาท
                        </p>
                    </div> */}
        </AntdCard>

        {/* Reference Details (Simulating Antd Descriptions/List) */}
        <AntdCard title="รายละเอียดอ้างอิง">
          <AntdRow>
            {paymentDetails.map((item, index) => (
              <AntdCol key={index} span={12}>
                <label style={styles.infoLabel}>{item.label}</label>
                <p
                  style={{
                    ...styles.infoValue,
                    color: item.primary
                      ? styles.antdPrimary
                      : styles.infoValue.color,
                    fontFamily: item.mono ? "monospace" : "inherit",
                  }}
                >
                  {item.value}
                </p>
              </AntdCol>
            ))}
          </AntdRow>
        </AntdCard>

        {/* Footer Note */}
        <div style={{ textAlign: "center", marginTop: "16px" }}>
          <p style={{ fontSize: "12px", color: "rgba(0, 0, 0, 0.45)" }}>
            ชำระได้ที่ธนาคารกรุงไทย ATM/Krungthai NEXT
            และช่องทางอิเล็กทรอนิกส์อื่นๆ
          </p>
          <p
            style={{
              fontSize: "12px",
              color: "rgba(0, 0, 0, 0.45)",
              marginTop: "4px",
            }}
          >
            โรงเรียนบัวแดงวัฒนา, โทรศัพท์ 081-276-7217
          </p>
        </div>
      </div>
    </div>
  );
};

export default QRPayment;
