import React, { useEffect, useState } from "react";
import {
  Button,
  Select,
  Divider,
  Modal,
  Space,
  Table,
  Checkbox,
  Tooltip,
  Typography,
  Radio,
} from "antd";
import { EditOutlined } from "@ant-design/icons";

import baseAPI from "../../api/baseAPI";
import AddStudentModal from "./AddStudentModal";
import EditStudentModal from "./EditStudentModal";
import GradeLevelModal from "./GradeLevelModal";
import StudentListExcel from "./excel/StudentListExcel";

const { Text } = Typography;

const gradeLevel = [
  "เตรียมอนุบาล",
  "อนุบาล 1",
  "อนุบาล 2",
  "อนุบาล 3",
  "ประถมศึกษาปีที่ 1",
  "ประถมศึกษาปีที่ 2",
  "ประถมศึกษาปีที่ 3",
  "ประถมศึกษาปีที่ 4",
  "ประถมศึกษาปีที่ 5",
  "ประถมศึกษาปีที่ 6",
  "มัธยมศึกษาปีที่ 1",
  "มัธยมศึกษาปีที่ 2",
  "มัธยมศึกษาปีที่ 3",
  "มัธยมศึกษาปีที่ 4",
  "มัธยมศึกษาปีที่ 5",
  "มัธยมศึกษาปีที่ 6",
];

export default function UserList() {
  const [studentList, setStudentList] = useState([]);
  const [studentListHolders, setStudentListHolders] = useState([]);
  const [dataSelected, setDataSelected] = useState(null);
  const [openAddStudentModal, setOpenAddStudentModal] = useState(false);
  const [openEditStudentModal, setOpenEditStudentModal] = useState(false);
  const [openGradeLevelModal, setOpenGradeLevelModal] = useState(false);
  const [radioSort, setRadioSort] = useState(1);
  // const [messageApi, contextHolder] = message.useMessage();

  useEffect(() => {
    getStudentList();
    // getGradeLevelList();
  }, []);

  const getStudentList = async () => {
    const result = await baseAPI.get(`/students`);
    const data = result.data;
    // console.log(data);
    setStudentList(data);
    setStudentListHolders(data);
  };

  // const getGradeLevelList = async () => {
  //   const result = await baseAPI.get(`/grade-levels`);
  //   const data = result.data;
  //   // console.log(data);
  //   setGradeList(data);
  // };

  const handleClickEdit = (data) => {
    setDataSelected(data);
    setOpenEditStudentModal(true);
    // console.log("EDIT", data);
  };

  const handleChangeGradeLevels = (value) => {
    // console.log("value", value);

    const result = studentListHolders.filter(
      (item) => item.grade_level === value
    );

    setStudentList(result);
  };

  const handleAddStudent = () => {
    setOpenAddStudentModal(true);
  };

  const handleSubmitEditStudent = (data) => {
    // console.log("DATA", data);
    Modal.confirm({
      title: "ยืนยันข้อมูล",
      content: "คุณต้องการเพิ่มรายชื่อนักเรียน ยืนยันข้อมูลหรือไม่?",
      centered: true,
      onOk: () => {
        setOpenEditStudentModal(false);
        updateStudent(data);
      },
    });
  };

  const updateStudent = async (data) => {
    await baseAPI
      .put(`/students`, data)
      .then((res) => {
        Modal.success({
          title: `สำเร็จ`,
          content: "แก้ไขรายการสำเร็จ",
          centered: true,
        });
        // getTermFeeList();
        const studentUpdate = studentList.map((student) => {
          if (student.id === data.id) {
            return { ...data };
          } else return { ...student };
        });
        setStudentList(studentUpdate);
      })
      .catch((err) => {
        Modal.error({
          title: `ผิดพลาด`,
          content: "Error: " + err.message,
          centered: true,
        });
      });
  };

  const insertStudent = async (data) => {
    await baseAPI
      .post(`/students`, data)
      .then((res) => {
        Modal.success({
          title: `สำเร็จ`,
          content: "เพิ่มรายชื่อนักเรียนสำเร็จ",
          centered: true,
        });
        getStudentList();
      })
      .catch((err) => {
        Modal.error({
          title: `ผิดพลาด`,
          content: "Error: " + err.message,
          centered: true,
        });
      });
  };

  const handleSubmitAddStudent = (data) => {
    // console.log("SubmitStudent", data);

    Modal.confirm({
      title: "ยืนยันข้อมูล",
      content: "คุณต้องการเพิ่มรายชื่อนักเรียน ยืนยันข้อมูลหรือไม่?",
      centered: true,
      onOk: () => {
        setOpenAddStudentModal(false);
        insertStudent(data);
      },
    });
  };

  const handleDeleteStudent = (data) => {
    Modal.confirm({
      title: "ลบรายชื่อ ",
      content:
        "คุณต้องการลบ " +
        data.title_name +
        data.fullname +
        " ออกจากระบบหรือไม่?",
      centered: true,
      onOk: () => {
        setOpenEditStudentModal(false);
        deleteStudentById(data);
      },
    });

    // setOpenGradeLevelModal(true);
  };

  const deleteStudentById = async (data) => {
    await baseAPI
      .delete(`/students/${data.id}`, data)
      .then((res) => {
        Modal.success({
          title: `สำเร็จ`,
          content: "ลบรายชื่อนักเรียนสำเร็จ",
          centered: true,
        });
        const newValue = studentList.filter((item) => item.id !== data.id);
        setStudentList(newValue);
        // getStudentList();
      })
      .catch((err) => {
        Modal.error({
          title: `ผิดพลาด`,
          content: "Error: " + err.message,
          centered: true,
        });
      });
  };

  const updateGradeLevel = async (data) => {
    await baseAPI
      .put(`/grade-levels/${data}`)
      .then((res) => {
        Modal.success({
          title: `สำเร็จ`,
          content: "เลื่อนระดับนักเรียนสำเร็จ",
          centered: true,
        });
        getStudentList();
      })
      .catch((err) => {
        Modal.error({
          title: `ผิดพลาด`,
          content: "Error: " + err.message,
          centered: true,
        });
      });
  };

  const handleSubmitGradeLevel = (data) => {
    let con = "";
    if (data === 1) con = "เลื่อนระดับนักเรียนทุกคน ขึ้น 1 ชั้น ";
    else con = "เลื่อนระดับนักเรียนทุกคน ลง 1 ชั้น ";
    Modal.confirm({
      title: "ยืนยันข้อมูล",
      content: con,
      centered: true,
      onOk: () => {
        setOpenGradeLevelModal(false);
        updateGradeLevel(data);
      },
    });
  };

  useEffect(() => {
    // console.log("RADIO", radioSort);
    // sortedValues = data.toSorted((a, b) => b.donate - a.donate);

    if (radioSort === 1) {
      const list = studentListHolders.toSorted(
        (a, b) => a.grade_level - b.grade_level
      );
      setStudentList(list);
    } else {
      const list = studentListHolders.toSorted((a, b) =>
        a.user_name.localeCompare(b.user_name)
      );
      setStudentList(list);
    }
  }, [radioSort]);

  useEffect(() => {
    console.log("Student", studentList);
  }, [studentList]);

  const onChangeSort = (e) => {
    setRadioSort(e.target.value);
  };

  const columns = [
    {
      title: "เลขประจำตัว",
      dataIndex: "student_id",
      key: "student_id",
    },
    {
      title: "ชื่อ-สกุล",
      //   dataIndex: 'address',
      key: "fullname",
      render: (recode) => {
        return (
          <Text>
            {recode.title_name}
            {recode.fullname}
          </Text>
        );
      },
    },
    {
      title: "ระดับชั้น/สถานะ",
      // dataIndex: "grade_level",
      key: "grade_level",
      render: (recode) => {
        const color = recode.status === "กำลังศึกษา" ? "success" : "danger";
        return (
          <Space direction="vertical">
            <Text>{recode.grade_level}</Text>
            <Text type={color}>{recode.status}</Text>
          </Space>
        );
      },
    },
    {
      title: "ประเภทนักเรียน/การชำระค่าเทอม",
      // dataIndex: "user_type",
      key: "user_type",
      render: (recode) => {
        // const color = recode.status === "กำลังศึกษา" ? "success" : "danger";
        return (
          <Space direction="vertical">
            <Text>{recode.user_type}</Text>
            <Text type="secondary">{recode.payment_type}</Text>
          </Space>
        );
      },
    },
    // {
    //   title: "ประเภทค่าเทอม",
    //   dataIndex: "mark",
    //   key: "mark",
    // },
    {
      title: "หมายเหตุ",
      dataIndex: "mark",
      key: "mark",
    },
    {
      title: "",
      // dataIndex: "edit",
      key: "edit",
      render: (recode) => {
        return (
          <Tooltip title="แก้ไข">
            <Button
              type="primary"
              shape="circle"
              icon={<EditOutlined />}
              onClick={() => handleClickEdit(recode)}
            />
          </Tooltip>
        );
      },
    },
  ];

  return (
    <div>
      <h2>รายชื่อนักเรียน</h2>
      <Divider />
      <div style={{ justifyContent: "space-between", display: "flex" }}>
        <>
          <Space>
            <Text strong>เลือกระดับชั้น</Text>
            <Select
              showSearch
              style={{ width: 200 }}
              placeholder="เลือกชั้นปี"
              onChange={handleChangeGradeLevels}
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
              options={gradeLevel.map((grade) => ({
                label: grade,
                value: grade,
              }))}
            />
          </Space>
        </>

        <>
          <Space>
            {/* <Button onClick={handleClickGradeLevel}>เลื่อนชั้นนักเรียน</Button> */}
            <Button type="primary" onClick={handleAddStudent}>
              เพิ่มรายชื่อนักเรียน
            </Button>
          </Space>
        </>
      </div>

      <Divider />
      <div
        style={{
          marginBottom: 16,
          flexDirection: "row",
          justifyContent: "space-between",
          display: "flex",
        }}
      >
        <Radio.Group onChange={onChangeSort} defaultValue={radioSort}>
          <Radio value={1}>เรียงตามลำดับชั้น</Radio>
          <Radio value={2}>เรียงตามเลขประจำตัว</Radio>
        </Radio.Group>
        <StudentListExcel data={studentList} />
      </div>

      <Table
        columns={columns}
        dataSource={studentList}
        bordered
        size="small"
        rowKey={"id"}
      />
      <AddStudentModal
        open={openAddStudentModal}
        onClose={setOpenAddStudentModal}
        onSubmit={handleSubmitAddStudent}
      />
      <EditStudentModal
        open={openEditStudentModal}
        data={dataSelected}
        onClose={setOpenEditStudentModal}
        onSubmit={handleSubmitEditStudent}
        onDelete={handleDeleteStudent}
      />
      <GradeLevelModal
        open={openGradeLevelModal}
        onClose={setOpenGradeLevelModal}
        onSubmit={handleSubmitGradeLevel}
      />
    </div>
  );
}
