import { useEffect, useState } from "react";
import { Modal, Form, InputNumber, Checkbox, Button, Space, Spin } from "antd";
import baseAPI from "../../api/baseAPI";

export default function FeeItemModal({ open, onClose, termFee }) {
  const [feeItems, setFeeItems] = useState([]);
  const [selectedItems, setSelectedItems] = useState({});
  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(false);

  const handleClose = () => {
    setFeeItems([]); // เคลียร์ทุกครั้งที่ปิด
    setSelectedItems({});
    onClose(false);
  };

  useEffect(() => {
    if (open && termFee?.id) {
      setInitialLoading(true);

      Promise.all([
        baseAPI.get("/fee-items"),
        baseAPI.get(`/termfee-items/${termFee.id}`),
      ])
        .then(([feeItemsRes, selectedRes]) => {
          setFeeItems(feeItemsRes.data);

          const selectedMap = {};
          selectedRes.data.forEach((item) => {
            selectedMap[item.fee_item_id] = { amount: item.amount };
          });
          setSelectedItems(selectedMap);
        })
        .catch((err) => console.error(err))
        .finally(() => setInitialLoading(false));
    }
  }, [open, termFee?.id]);

  const handleCheckChange = (itemId, checked) => {
    setSelectedItems((prev) => {
      const newSelected = { ...prev };
      if (checked) {
        newSelected[itemId] = { amount: newSelected[itemId]?.amount || 0 };
      } else {
        delete newSelected[itemId];
      }
      return newSelected;
    });
  };

  const handleAmountChange = (itemId, value) => {
    setSelectedItems((prev) => ({
      ...prev,
      [itemId]: { amount: value },
    }));
  };

  const onSubmit = async () => {
    const data = Object.entries(selectedItems).map(
      ([feeItemId, { amount }]) => ({
        term_fee_id: termFee.id,
        fee_item_id: parseInt(feeItemId),
        amount,
      })
    );

    try {
      setLoading(true);
      await baseAPI.post("/termfee-items", { items: data });
      setLoading(false);
      Modal.success({
        title: `อัพเดตข้อมูลสำเร็จ`,
        // content: "",
        centered: true,
      });
      handleClose();
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  return (
    <Modal
      open={open}
      onCancel={handleClose}
      title="เลือกค่าธรรมเนียม"
      footer={null}
      width={600}
    >
      {initialLoading ? (
        <div className="text-center py-10">
          <Spin />
        </div>
      ) : (
        <Form layout="vertical">
          <Space direction="vertical" style={{ width: "100%" }}>
            {feeItems.map((item) => {
              const isSelected = selectedItems[item.id] !== undefined;
              return (
                <Space
                  key={item.id}
                  style={{ display: "flex", justifyContent: "space-between" }}
                >
                  <Checkbox
                    checked={isSelected}
                    onChange={(e) =>
                      handleCheckChange(item.id, e.target.checked)
                    }
                  >
                    {item.name}
                  </Checkbox>

                  {isSelected && (
                    <InputNumber
                      value={selectedItems[item.id]?.amount}
                      min={0}
                      step={100}
                      onChange={(value) => handleAmountChange(item.id, value)}
                      placeholder="ใส่ราคา"
                      formatter={(value) =>
                        `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                      }
                    />
                  )}
                </Space>
              );
            })}

            <Button type="primary" onClick={onSubmit} loading={loading}>
              บันทึกข้อมูล
            </Button>
          </Space>
        </Form>
      )}
    </Modal>
  );
}
