import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import {
  currencyFormat,
  formatThreeDigits,
  getBase64ImageFromURL,
} from "../../../utils/Utils";
import { ArabicNumberToText } from "../../../utils/thaibath";
import LOGO from "../../../assests/images/receipt-logo.png";
import SEAL from "../../../assests/images/Seal.png";
import RECEIVER from "../../../assests/images/Receiver.png";
import moment from "moment";

pdfMake.vfs = pdfFonts.pdfMake.vfs;

export const generateReceiptPDF = async (receiptData, receiptType) => {
  const {
    fullname,
    student_id,
    grade_level,
    amount_paid,
    term_fee_items,
    year,
    semester,
    term_fees,
    data_count,
    title_name,
    payment_date,
  } = receiptData;

  const yearThai = ~~year + 543;
  // console.log(yearThai);

  // const yearEducation = moment(yearThai).format("YYYY");
  const billNo = `${formatThreeDigits(semester)}/${yearThai}`;
  const volumeNo = `${yearThai - 2500}${formatThreeDigits(data_count)}`;

  const tableBody = [
    [
      { text: "ลำดับ", bold: true },
      { text: "รายการ", bold: true },
      { text: "จำนวนเงิน (บาท)", bold: true },
    ],
  ];

  term_fee_items.forEach((item, index) => {
    tableBody.push([
      index + 1,
      item.name,
      { text: currencyFormat(item.amount), alignment: "center" },
    ]);
  });

  let currentRowCount = term_fee_items.length;

  if (receiptType === 2) {
    while (currentRowCount < 19) {
      tableBody.push([
        currentRowCount + 1,
        "",
        { text: "", alignment: "center" },
      ]);
      currentRowCount++;
    }

    tableBody.push([
      { text: "ส่วนลด", colSpan: 2, alignment: "center", bold: true },
      {},
      {
        text: currencyFormat(term_fees - amount_paid),
        alignment: "center",
        bold: true,
      },
    ]);
    tableBody.push([
      { text: "รวม", colSpan: 2, alignment: "center", bold: true },
      {},
      { text: currencyFormat(amount_paid), alignment: "center", bold: true },
    ]);
  } else {
    while (currentRowCount < 20) {
      tableBody.push([
        currentRowCount + 1,
        "",
        { text: "", alignment: "center" },
      ]);
      currentRowCount++;
    }

    tableBody.push([
      { text: "รวม", colSpan: 2, alignment: "center", bold: true },
      {},
      { text: currencyFormat(term_fees), alignment: "center", bold: true },
    ]);
  }

  // เติมแถวเปล่าให้ครบ 25 แถว

  tableBody.push([
    {
      text: ArabicNumberToText(term_fees), // จำนวนเงินเป็นตัวอักษร (ตรงนี้จะ fix ไว้ก่อน)
      italics: true,
      bold: true,
      colSpan: 3,
      alignment: "center",
      //   margin: [0, 30, 0, 0],
    },
    {},
    {},
  ]);

  const docDefinition = {
    content: [
      {
        columnGap: 10,
        columns: [
          {
            image: await getBase64ImageFromURL(LOGO),
            width: 100,
            height: 100,
            alignment: "center",
          },
          {
            margin: [20, 5, 0, 0],
            stack: [
              {
                text: `โรงเรียนบัวแดงวัฒนา`,
                // alignment: "center",
                fontSize: 16,
                bold: true,
                margin: [0, 0, 0, 10], // เพิ่ม margin ด้านล่างเล็กน้อย
              },

              {
                text: `ที่อยู่ 227/431 ซ.ประชาสโมสร 52 ต.ในเมือง อ.เมือง จ.ขอนแก่น 40000\r\nเลขประจำตัวผู้เสียภาษีอากร 0994002773762 \r\nโทร. 081 276 7271`,
                // alignment: "center",
                fontSize: 12,
                // bold: true,
                // lineHeight: 1.5, // เพิ่มความสูงของบรรทัด
                // margin: [0, 5, 0, 5], // เพิ่ม margin บนและล่างเล็กน้อย
              },
            ],
            width: "*",
          },
          {
            stack: [
              {
                text: `เล่มที่ ${billNo}`,
                alignment: "right",
                bold: true,
                // margin: [0, 0, 0, 5], // เพิ่ม margin ด้านล่างเล็กน้อย
              },
              {
                text: `เลขที่ ${volumeNo}`,
                alignment: "right",
                bold: true,
                //, // เพิ่ม margin ด้านบนเล็กน้อย
              },
            ],
            width: "auto",
            alignment: "top", // จัดกลุ่มเลขที่ไว้ด้านบน
          },
        ],
      },
      // {
      //   canvas: [
      //     {
      //       type: "line",
      //       x1: 0, // จุดเริ่มต้นของเส้น (แกน X ซ้ายสุด)
      //       y1: 0, // จุดเริ่มต้นของเส้น (แกน Y)
      //       x2: 535, // จุดสิ้นสุดของเส้น (แกน X ขวาสุด)
      //       y2: 0, // จุดสิ้นสุดของเส้น (แกน Y เดิม = แนวนอน)
      //       lineWidth: 0.5, // ความหนาของเส้น
      //       lineColor: "black", // สีของเส้น
      //       // dash: { length: 5, space: 3 }, // ความยาวเส้นและช่องว่างระหว่างประ
      //     },
      //   ],
      //   margin: [0, 20, 0, 20],
      // },
      {
        text: "ใบเสร็จรับเงิน",
        alignment: "center",
        fontSize: 20,
        bold: true,
        margin: [0, 0, 0, 0], // เพิ่มระยะห่างจากส่วนหัว
      },
      {
        text: `วันที่ชำระ: ${moment(payment_date)
          .add(-7, "hours")
          .add(543, "years")
          .format("LL")}`,
        // width: "60%",
        alignment: "right",
        // bold: true,
        // fontSize: 14,
      },
      {
        columns: [
          {
            text: `ชื่อ-สกุล:\t${title_name}${fullname}`,
            width: "60%",
            bold: true,
            fontSize: 14,
          },
          {
            text: `รหัสนักเรียน:\t${student_id}`,
            width: "40%",
            bold: true,
            fontSize: 14,
          },
        ],
      },
      {
        columns: [
          {
            text: `ลำดับชั้น:\t${grade_level}`,
            width: "60%",
            bold: true,
            fontSize: 14,
          },
          {
            text: `ภาคเรียนที่ ${semester} ปีการศึกษา ${year + 543}`,
            width: "40%",
            bold: true,
            fontSize: 14,
          },
        ],
        margin: [0, 0, 0, 10],
      },
      {
        table: {
          widths: ["auto", "*", "auto"],
          body: tableBody,
        },
      },

      {
        columns: [
          {
            stack: [
              {
                text: "ลายมือผู้รับเงิน",
                width: "50%",
                fontSize: 14,
                bold: true,
                alignment: "center",
                margin: [0, 10, 0, 0],
              },
              {
                text: "................................................................",
                width: "50%",
                fontSize: 14,
                bold: true,
                // decorationStyle: "dotted",
                alignment: "center",
                margin: [0, 15, 0, 0],
              },
              {
                text: `วันที่\t ${moment(payment_date)
                  .add(-7, "hours")
                  .add(543, "years")
                  .format("LL")}`,
                width: "50%",
                fontSize: 14,
                // decorationStyle: "dotted",
                bold: true,
                alignment: "center",
                margin: [0, 10, 0, 0],
              },
            ],
          },
          {
            stack: [
              {
                text: "ลายมือผู้ปกครอง",
                width: "50%",
                fontSize: 14,
                bold: true,
                alignment: "center",
                margin: [0, 10, 0, 0],
              },
              {
                text: "................................................................",
                width: "50%",
                fontSize: 14,
                bold: true,
                // decorationStyle: "dotted",
                alignment: "center",
                margin: [0, 15, 0, 0],
              },
              // {
              //   text: "วันที่: .........................................................",
              //   width: "50%",
              //   fontSize: 14,
              //   bold: true,
              //   alignment: "center",
              //   margin: [0, 10, 0, 0],
              // },
            ],
          },
        ],
      },
      {
        image: await getBase64ImageFromURL(RECEIVER),
        width: 100,
        absolutePosition: { x: 120, y: 730 },
      },
      {
        image: await getBase64ImageFromURL(SEAL),
        width: 150,
        absolutePosition: { x: 200, y: 680 },
      },
    ],

    defaultStyle: { font: "THSarabunNew" },
    styles: {
      header: {
        fontSize: 20,
        bold: true,
      },
      withMargin: {
        margin: [20, 20, 20, 20],
      },
      alignCenter: {
        alignment: "center",
      },

      textBody: {
        fontSize: 16,
      },
      subheader: {
        fontSize: 15,
        bold: true,
      },
      quote: {
        italics: true,
      },
      small: {
        fontSize: 8,
      },
    },
  };

  return docDefinition;
};
