import React, { useState, useRef, useEffect } from "react";
import {
  Card,
  Typography,
  Descriptions,
  Divider,
  Space,
  Button,
  Tag,
} from "antd";

import { useDispatch, useSelector } from "react-redux";
import { useParams, Link, useNavigate } from "react-router-dom";
import baseAPI from "../../api/baseAPI";
import QRCode from "qrcode";
// import Barcode from "react-barcode";
import JsBarcode from "jsbarcode";
import {
  currencyFormat,
  currencyFormatTH,
  extractNumbers,
} from "../../utils/Utils";
// import TermPaymentQRCode from "./TermPaymentQRCode";
import { TermPaymentPDF } from "./pdf/TermPaymentPDF";

import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts"; // นำเข้า vfs_fonts
import { generateReceiptPDF } from "../term_fees/pdf/Receipt";
import { generateTemporaryReceiptPDF } from "../term_fees/pdf/ReceiptTemporary";
import TermFeeHistoryModal from "../term_fees/TermFeeHistoryModal";

// // ตรวจสอบให้มั่นใจว่า vfs ฟอนต์ถูกตั้งค่า
// pdfMake.vfs = pdfFonts.pdfMake.vfs; // ตั้งค่า VFS ฟอนต์

// ต้องระบุตามชื่อของ ไฟล์ font
pdfMake.fonts = {
  THSarabunNew: {
    normal: "THSarabunNew.ttf",
    bold: "THSarabunNew Bold.ttf",
    italics: "THSarabunNew Italic.ttf",
    bolditalics: "THSarabunNew Bold Italic.ttf",
  },
  AngsanaNew: {
    normal: "AngsanaNew.ttf",
    bold: "AngsanaNew Bold.ttf",
    italics: "AngsanaNew Italic.ttf",
    bolditalics: "AngsanaNew Bold Italic.ttf",
  },
  Roboto: {
    normal: "Roboto-Regular.ttf",
    bold: "Roboto-Medium.ttf",
    italics: "Roboto-Italic.ttf",
    bolditalics: "Roboto-MediumItalic.ttf",
  },
};

pdfMake.vfs = pdfFonts.pdfMake.vfs;

const { Text } = Typography;

export default function TermPayment() {
  const user = useSelector((state) => state.userData);
  const [termList, setTermList] = useState([]);
  // const [dataSelected, setDataSelected] = useState(null);
  const [openPaymentListModal, setOpenPaymentListModal] = useState(false);
  const [termFeeList, setTermFeeList] = useState(false);
  // const [dataPDF, setDataPDF] = useState({});

  const navigate = useNavigate();
  // const canvasRef = useRef(null);

  useEffect(() => {
    getTermPaymentList();
    console.log("User", user);
  }, [user]);

  const getTermPaymentList = async () => {
    const result = await baseAPI.get(`terms/student/${user.id}`);
    const data = result.data;

    setTermList(data);
  };

  // const handleClickPayment = (data) => {
  //   setOpenTermSelected(data);
  //   setOpenTermPayModal(true);
  // };

  const generateQRCodeAndBarcode = async (data) => {
    const year = data.year + 543;
    const studentNumber = extractNumbers(data.student_id);
    // const studentNumber = "0000";
    let amount = 0;
    if (user.payment_type === "จ่ายครั้งเดียว") {
      amount = data?.term_fees;
    } else {
      amount = data?.term_fees / 3;
    }

    amount = Math.ceil(amount);

    const obj = {
      prefix: "|",
      taxId: "0994002773762",
      suffix: "01",
      ref1: year - 2500 + "" + data.term_number + "0",
      ref2: studentNumber,
      amount: amount * 100,
    };
    // setDetail(obj);

    const barcode =
      // QRCODE_URL +
      // "/qr/" +
      obj.prefix +
      obj.taxId + // เลขประจำตัวผู้เสียภาษี
      obj.suffix +
      "\r\n" +
      obj.ref1 + // REF1
      "\r\n" +
      obj.ref2 + // REF2
      "\r\n" +
      obj.amount; // จำนวนเงินชำระ

    // setBarCodeValue(barcode);

    const qrcodeImg = await generateQRCode(obj);
    const qrcode = await imageToBase64(qrcodeImg);

    // setQrcode(qrcode);
    const tempCanvas = document.createElement("canvas");

    // if (canvasRef.current) {
    JsBarcode(tempCanvas, barcode, {
      format: "CODE128",
      width: 2,
      height: 60,
      displayValue: true,
    });

    // แปลง <canvas> เป็น Base64
    const base64Image = tempCanvas.toDataURL("image/png");
    return { amount, qrcode, base64Image };
  };

  const handleClickPDF = async (data) => {
    // console.log("PDF", data);
    // setDataSelected(data);
    const { amount, qrcode, base64Image } = await generateQRCodeAndBarcode(
      data
    );

    let result = await TermPaymentPDF(
      { ...data, term_fees: amount },
      qrcode,
      base64Image
    );
    pdfMake.createPdf(result).open();
    // }
  };

  const generateQRCode = async (formData) => {
    const { prefix, taxId, suffix, ref1, ref2, amount } = formData;

    // ฟอร์แมตข้อมูลตามที่กำหนด
    const formattedData = `${prefix}${taxId}${suffix}\r\n${ref1}\r\n${ref2}\r\n${amount}`;

    try {
      const qrCodeUrl = await QRCode.toDataURL(formattedData);
      return qrCodeUrl;
    } catch (err) {
      console.error(err);
    }
  };

  const imageToBase64 = async (url) => {
    const response = await fetch(url); // ดึงรูปภาพจาก URL
    const blob = await response.blob(); // แปลงเป็น Blob
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result); // แปลงเป็น Base64
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  };

  const fetchTermFeeHistory = async (year) => {
    const result = await baseAPI.get(`/payments/users`, {
      params: { user_id: user.id, year },
    });
    const data = result.data;
    console.log(data);
    setTermFeeList(data);
    setOpenPaymentListModal(true);
  };

  const handlePrintReceipt = async (data) => {
    const result = await baseAPI.get(`/receipt/payment/${data.id}`);
    console.log("PRINT", result.data);
    setOpenPaymentListModal(false);
    // setOpenReceiptTypeModal(true);

    // setDataPDF(result.data);
    handleClickPrint(result.data);
  };

  const handleClickPrint = (data) => {
    let userType = 0;
    if (user.payment_type === "จ่ายครั้งเดียว") {
      switch (user.user_type) {
        case "ทั่วไป":
          userType = 1;
          break;
        case "ลูกครู":
          userType = 2;
          break;
        case "ลูกคนที่ 2":
          userType = 2;
          break;
        default:
          break;
      }
    } else {
      userType = 3;
    }
    // setSelectedReceiptType(value);
    // console.log("ประเภทใบเสร็จที่เลือก:", value);
    // setOpenReceiptTypeModal(false);
    if (userType !== 3) {
      onDownloadReceiptPDF(data, userType);
    } else {
      onDownloadTemporaryReceiptPDF(data);
      // console.log("Value:", value);
    }
    // ทำอย่างอื่นกับค่าที่เลือก เช่น ส่งไปยัง API
  };

  const onDownloadReceiptPDF = async (data, type) => {
    const docDefinition = await generateReceiptPDF(data, type);
    pdfMake.createPdf(docDefinition).download("termfee.pdf");
  };

  const onDownloadTemporaryReceiptPDF = async (data) => {
    const docDefinition = await generateTemporaryReceiptPDF(data);
    pdfMake.createPdf(docDefinition).download("termfee.pdf");
  };

  const handleClickQrcode = async (data) => {
    const { amount, qrcode, base64Image } = await generateQRCodeAndBarcode(
      data
    );
    navigate("/term-payment/qrpayment", {
      state: {
        data: { ...data, term_fees: amount },
        qrcode,
        base64Image,
      },
    });
  };

  const RenderItem = ({ item }) => {
    const disable = item.status === "ปิดรับ" ? true : false;
    const color = item.status === "ปิดรับ" ? "secondary" : "success";
    return (
      <div>
        <div
          style={{
            justifyContent: "space-between",
            display: "flex",
            alignItems: "center",
          }}
        >
          <h4>
            ปีการศึกษา {item?.year + 543} /{currencyFormatTH(item?.term_fees)}{" "}
            <Text type={color}>({item.status})</Text>
          </h4>
          <Button type="link" onClick={() => fetchTermFeeHistory(item.year)}>
            พิมพ์ใบเสร็จ
          </Button>
        </div>

        <div style={{ display: "flex", justifyContent: "space-between" }}>
          <Space direction="vertical">
            <Space>
              <Space direction="vertical">
                <Button
                  disabled={disable}
                  type="primary"
                  // onClick={() => handleClickPayment({ ...item, term_number: 1 })}
                  onClick={() => handleClickPDF({ ...item, term_number: 1 })}
                >
                  เทอม 1 Bank (PDF)
                </Button>
                <Button
                  disabled={disable}
                  type="primary"
                  // onClick={() => handleClickPayment({ ...item, term_number: 1 })}
                  onClick={() => handleClickQrcode({ ...item, term_number: 1 })}
                >
                  เทอม 1 QRCode
                </Button>
              </Space>

              <Text>
                ชำระแล้ว{" "}
                {item.total_paid_sem1
                  ? currencyFormat(item.total_paid_sem1)
                  : 0}{" "}
                บาท{" "}
                {item?.term_fees ? (
                  item.total_paid_sem1 >= item?.term_fees ? (
                    <>{!disable && <Tag color="success">ครบแล้ว</Tag>}</>
                  ) : (
                    <>{!disable && <Tag color="processing">ยังไม่ครบ</Tag>}</>
                  )
                ) : null}
              </Text>
            </Space>
            <Space>
              <Space direction="vertical">
                <Button
                  type="primary"
                  disabled={disable}
                  // onClick={() => handleClickPayment({ ...item, term_number: 2 })}
                  onClick={() => handleClickPDF({ ...item, term_number: 2 })}
                >
                  เทอม 2 Bank (PDF)
                </Button>
                <Button
                  disabled={disable}
                  type="primary"
                  // onClick={() => handleClickPayment({ ...item, term_number: 1 })}
                  onClick={() => handleClickQrcode({ ...item, term_number: 1 })}
                >
                  เทอม 2 QRCode
                </Button>
              </Space>

              <Text>
                ชำระแล้ว{" "}
                {item?.total_paid_sem2
                  ? currencyFormat(item?.total_paid_sem2)
                  : 0}{" "}
                บาท{" "}
                {item?.term_fees ? (
                  item?.total_paid_sem2 >= item?.term_fees ? (
                    <>{!disable && <Tag color="success">ครบแล้ว</Tag>}</>
                  ) : (
                    <>{!disable && <Tag color="processing">ยังไม่ครบ</Tag>}</>
                  )
                ) : null}
              </Text>
            </Space>
          </Space>
        </div>

        {/* {barcodeImage && <img src={barcodeImage} alt="Generated Barcode" />} */}

        <Divider />
      </div>
    );
  };

  return (
    <div>
      <h2>ชำระค่าเทอม</h2>
      <Divider />
      {/* <Card title="รายละเอียด"> */}
      <Descriptions title="ข้อมูลนักเรียน">
        <Descriptions.Item label="ชื่อผู้ใช้งาน">
          {user.user_name}
        </Descriptions.Item>
        <Descriptions.Item label="ชื่อ-สกุล">
          {user.titlename} {user.fullname}
        </Descriptions.Item>
        <Descriptions.Item label="เลขประจำตัวประชาชน">
          {user.idcard}
        </Descriptions.Item>
        <Descriptions.Item label="รหัสนักเรียน">
          {user.student_id}
        </Descriptions.Item>
        <Descriptions.Item label="ระดับชั้น">
          {user.grade_level}
        </Descriptions.Item>

        <Descriptions.Item label="หมายเหตุ">{user.mark}</Descriptions.Item>
        <Descriptions.Item label="ประเภทการชำระ">
          {user.payment_type}
        </Descriptions.Item>
      </Descriptions>
      {/* </Card> */}
      <Divider />
      <Card title="ประวัติการชำระค่าเทอม">
        {termList?.map((item, index) => (
          <RenderItem key={index} item={item} />
        ))}
      </Card>
      <TermFeeHistoryModal
        open={openPaymentListModal}
        onClose={setOpenPaymentListModal}
        data={termFeeList}
        onPrint={handlePrintReceipt}
      />
    </div>
  );
}
