import * as React from "react";
import { styled, useTheme } from "@mui/material/styles";

import {
  Box,
  Drawer,
  AppBar,
  Toolbar,
  List,
  Typography,
  Divider,
  IconButton,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Link,
  Menu,
  MenuItem,
  Button,
} from "@mui/material";
import { Link as RouterLink, useNavigate } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";

import {
  Groups as GroupsIcon,
  Menu as MenuIcon,
  Close as CloseIcon,
  Info as InfoIcon,
  Call as CallIcon,
  AccountCircle as AccountCircleIcon,
  Payment as PaymentlIcon,
  Contacts as ContactsIcon,
} from "@mui/icons-material";
import { ClickAwayListener } from "@mui/base";

import logo from "../assests/images/bdw-s-logo.png";
import { COLOR } from "../utils/theme";
import { Modal, Space } from "antd";
import { addUserData } from "../store/tokenSlice";
// import { addToken } from "components/store/tokenSlice";

const drawerWidth = 240;

const DrawerHeader = styled("div")(({ theme }) => ({
  // color: "gray",
  display: "flex",
  alignItems: "center",
  padding: theme.spacing(0, 1),
  // necessary for content to be below app bar
  ...theme.mixins.toolbar,
  // justifyContent: "flex-end",
}));

export default function Header() {
  const dispatch = useDispatch();
  const user = useSelector((state) => state.userData);
  const navigate = useNavigate();
  const theme = useTheme();
  const [open, setOpen] = React.useState(false);
  const [anchorEl, setAnchorEl] = React.useState(null);
  const openMenuItem = Boolean(anchorEl);

  const handleDrawerOpen = () => {
    setOpen(true);
  };

  const handleDrawerClose = () => {
    setOpen(false);
  };

  const handleClickMenuItem = (event) => {
    setAnchorEl(event.currentTarget);
  };
  const handleCloseMenuItem = () => {
    setAnchorEl(null);
  };

  const handleSelectedMenuItem = (event) => {
    console.log(event.target.value);
    switch (event.target.value) {
      case 1:
        navigate("/users/" + user.id);
        break;
      case 2:
        navigate("/users/auction-list/" + user.id);
        break;
      case 3:
        Modal.confirm({
          title: "ออกจากระบบ",
          content: "คุณต้องการออกจากระบบหรือไม่?",
          centered: true,
          onOk() {
            dispatch(addUserData(null));
            // navigate("/login");
          },
        });

        break;
      default:
        break;
    }
  };

  const menuAdmin = [
    // { name: "ชำระค่าเทอม", icon: <PaymentlIcon />, route: "term-payment" },
    {
      name: "รายการชำระค่าเทอม",
      icon: <ContactsIcon />,
      route: "term-payment-list",
    },
    {
      name: "รายชื่อนักเรียน",
      icon: <GroupsIcon />,
      route: "users",
    },
  ];

  const menuStudent = [
    { name: "ชำระค่าเทอม", icon: <PaymentlIcon />, route: "term-payment" },
    // {
    //   name: "รายการชำระค่าเทอม",
    //   icon: <ContactsIcon />,
    //   route: "term-payment-list",
    // },
    // {
    //   name: "รายชื่อนักเรียน",
    //   icon: <GroupsIcon />,
    //   route: "users",
    // },
  ];

  const menuList2 = [
    { name: "081 276 7217", icon: <CallIcon /> },
    // { name: "ออกจากระบบ", icon: <LogoutIcon /> },
  ];

  const renderItem = ({ data, index }) => {
    // console.log(data);
    return (
      <ListItem
        // button={true}
        key={index}
        disablePadding
        to={data.route}
        component={RouterLink}
      >
        <ListItemButton>
          <ListItemIcon>{data.icon}</ListItemIcon>
          <ListItemText
            primary={data.name}
            primaryTypographyProps={{
              // fontSize: 22,
              color: "black",
            }}
          />
        </ListItemButton>
      </ListItem>
    );
  };

  const logoShow = () => {
    let path = "";
    // if (user.role === "admin" || user.role === "user") {
    //   path = "/products";
    // } else {
    //   path = "/retails";
    // }
    return (
      <Link to={path} color="inherit" component={RouterLink} underline="none">
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
          }}
        >
          <img
            src={logo}
            width={45}
            alt="ONE Logo"
            style={{ marginRight: 16 }}
          />
          <Typography variant="h6" noWrap component="div">
            บัวแดงวัฒนา
          </Typography>
        </div>
      </Link>
    );
  };

  return (
    <ClickAwayListener
      mouseEvent="onMouseDown"
      touchEvent="onTouchStart"
      onClickAway={() => open && setOpen(false)}
    >
      <Box sx={{ display: "flex" }}>
        <AppBar
          style={{ backgroundColor: COLOR.primary }}
          position="fixed"
          open={open}
        >
          <Toolbar>
            <IconButton
              color="inherit"
              aria-label="open drawer"
              onClick={handleDrawerOpen}
              edge="start"
              sx={{ mr: 2, ...(open && { display: "none" }) }}
            >
              <MenuIcon />
            </IconButton>
            {!open ? logoShow() : null}
            <div style={{ flexGrow: 1 }}></div>
            <div
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
              }}
            >
              <div>
                <IconButton
                  color="inherit"
                  id="basic-button"
                  aria-controls={openMenuItem ? "basic-menu" : undefined}
                  aria-haspopup="true"
                  aria-expanded={openMenuItem ? "true" : undefined}
                  onClick={handleClickMenuItem}
                >
                  <AccountCircleIcon fontSize="large" />
                </IconButton>
                <Menu
                  id="basic-menu"
                  anchorEl={anchorEl}
                  open={openMenuItem}
                  onClick={handleSelectedMenuItem}
                  onClose={handleCloseMenuItem}
                  MenuListProps={{
                    "aria-labelledby": "basic-button",
                  }}
                >
                  <MenuItem value={1} onClick={handleCloseMenuItem}>
                    โปรไฟล์ของฉัน
                  </MenuItem>

                  <MenuItem value={3} onClick={handleCloseMenuItem}>
                    ออกจากระบบ
                  </MenuItem>
                </Menu>
              </div>
            </div>
          </Toolbar>
        </AppBar>

        <Drawer
          sx={{
            width: drawerWidth,

            flexShrink: 0,
            "& .MuiDrawer-paper": {
              width: drawerWidth,
              boxSizing: "border-box",
            },
          }}
          variant="persistent"
          anchor="left"
          open={open}
        >
          <DrawerHeader>
            {logoShow()}
            <div style={{ flexGrow: 1 }}></div>
            <IconButton onClick={handleDrawerClose}>
              {theme.direction === "ltr" ? <CloseIcon /> : <CloseIcon />}
            </IconButton>
          </DrawerHeader>
          <Divider />

          <List>
            {user.role_id === 1 &&
              menuAdmin.map((data, index) => renderItem({ data, index }))}
            {user.role_id === 2 &&
              menuStudent.map((data, index) => renderItem({ data, index }))}
          </List>
          <Divider />
          <List>
            {menuList2.map((data, index) => renderItem({ data, index }))}
          </List>
        </Drawer>
      </Box>
    </ClickAwayListener>
  );
}
