import React, { useEffect, useState } from "react";
import { Modal, Button, Typography, Divider, Input } from "antd";
// import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import moment from "moment";

const { Text } = Typography;
const { TextArea } = Input;

export default function AddFeeItemModal({ open, onSubmit, onClose }) {
  const [name, setName] = useState("");

  const handleClose = () => {
    onClose(false);
  };

  const handleSubmit = () => {
    onSubmit(name);
  };

  return (
    <Modal
      title="เพิ่มรายการค่าใช้จ่าย"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        <Button key="submit" type="primary" onClick={handleSubmit}>
          เพิ่ม
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <div style={{ justifyContent: "space-between", display: "flex" }}>
          <Text style={{ flex: 1 }} strong>
            ชื่อค่าใช้จ่าย
          </Text>
          <Input
            style={{ flex: 2 }}
            placeholder="ชื่อค่าใช้จ่าย"
            onChange={(e) => setName(e.target.value)}
          />
          {/* <Space>
            <DatePicker picker="year" onChange={onChangeDate} />
            <Text strong>{moment(year).add(543, "years").format("YYYY")}</Text>
          </Space> */}
        </div>
        {/* <TextArea placeholder="รายละเอียด (ถ้ามี)" rows={2} /> */}

        <Divider />
      </div>
    </Modal>
  );
}
