import React from "react";
import { saveAs } from "file-saver";
import ExcelJS from "exceljs";
import { Button } from "antd";
import moment from "moment";
import { currencyFormat } from "../../../utils/Utils";

export default function StudentListExcel({ data }) {
  const exportToExcel = () => {
    const workbook = new ExcelJS.Workbook();
    const worksheet1 = workbook.addWorksheet("รายชื่อนักเรียน");

    worksheet1.columns = [
      { header: "รหัสนักเรียน", key: "student_id", width: 15 },
      { header: "คำนำหน้า", key: "title_name", width: 10 },
      { header: "ชื่อ-สกุล", key: "fullname", width: 30 },
      { header: "ระดับชั้น", key: "grade_level", width: 20 },
      { header: "ประเภท", key: "user_type", width: 15 },
      { header: "สถานะภาพ", key: "status", width: 15 },
    ];

    worksheet1.getRow(1).eachCell((cell) => {
      cell.fill = {
        type: "pattern",
        pattern: "solid",
        fgColor: { argb: "FFCCFFCC" },
      };
      cell.font = { bold: true };
    });

    data.forEach((item, index) => {
      const row = worksheet1.addRow({
        student_id: item.student_id,
        title_name: item.title_name,
        fullname: item.fullname,
        grade_level: item.grade_level,
        user_type: item.user_type,
        status: item.status,
      });

      // Fill alternate row background color
      if (index % 2 === 0) {
        row.eachCell((cell) => {
          cell.fill = {
            type: "pattern",
            pattern: "solid",
            fgColor: { argb: "FFEDEDED" },
          };
        });
      }
    });

    workbook.xlsx.writeBuffer().then((buffer) => {
      const blob = new Blob([buffer], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      });
      saveAs(blob, `รายชื่อนักเรียน.xlsx`);
    });
  };

  return (
    <div
      style={{
        width: "100%",
        display: "flex",
        justifyContent: "flex-end",
        marginBottom: 24,
      }}
    >
      <Button type="primary" onClick={exportToExcel}>
        ดาวน์โหลด Excel
      </Button>
    </div>
  );
}
